return array (
  'title' => 'Convierta PowerPoint a PDF para presentaciones y folletos',
  'description' => 'Aprenda a convertir diapositivas de PowerPoint a PDF para distribuirlas, compartirlas y visualizarlas de manera confiable. Cubre diseños, notas, tamaño de archivo y cómo revisar las diapositivas antes de enviarlas.',
  'main-heading' => 'Convierta PowerPoint a PDF para presentaciones y folletos',
